 ar:{nav:"ترابط الأحداث",eyebrow:"الروابط بين حياة الناس",title:"رحلة واحدة، ومصائر عديدة.",intro:"تتبّع الفروع من الرحلة المخططة إلى الغرق والإنقاذ وما بعدهما.",hint:"اختر عقدة أو مفتاحًا لإبراز الفروع المرتبطة وقراءة قصتها. اختره مجددًا أو اضغط Esc لعرض الكل.",scrollHint:"مرّر أفقيًا لاستكشاف المخطط كاملًا.",diagramLabel:"مخطط ترابط أحداث لشبونة مارو",legendLabel:"مفتاح المخطط",selectLabel:"اختر حدثًا",overview:"جميع الأحداث",reset:"اعرض الكل",detailLabel:"عن هذا الحدث",sourceLink:"اقرأ المصدر",fishermenUnit:"صيادًا",rescuedMeta:"إنقاذ 384 أسيرًا",categories:{planned:"الرحلة المخططة",actual:"الأحداث وما بعدها",place:"مكان",attack:"الهجوم والغرق",death:"المتوفون",captive:"الأسرى",survivor:"الناجون / الهاربون",rescue:"إنقاذ الصيادين"},categoryDescriptions:{planned:"يُظهر الخط المتقطع نحو موجي الرحلة المخططة. لم تصل لشبونة مارو إلى اليابان.",actual:"تربط الخطوط المتصلة الأحداث والمصائر اللاحقة، لا المسار الدقيق للسفينة.",place:"تحدد الدوائر المزدوجة هونغ كونغ ودونغجي وموجي والمملكة المتحدة، وتربط المغادرة والإنقاذ والعودة.",attack:"أُصيبت السفينة بطوربيد في الأول من أكتوبر 1942، وغرقت في اليوم التالي.",death:"توفي 828 أسير حرب بريطانيًا، أي نحو 46% ممن كانوا على متن السفينة.",captive:"يميز العدد 604 مسارًا أوليًا عن إنقاذ الصيادين. ومن بين 384 رجلًا أنقذهم الصيادون، أُسر 381 مجددًا.",survivor:"يُحصي 384 من أنقذهم الصيادون، ويُحصي ثلاثة من نجوا من إعادة الأسر. هذه مراحل مختلفة، لا نتائج نهائية متكافئة.",rescue:"شارك 198 صيادًا في إنقاذ 384 أسير حرب بريطانيًا."},nodes:{hongkong:{title:"هونغ كونغ (الحكم البريطاني)",meta:"27 سبتمبر 1942 · 1,816 أسيرًا بريطانيًا",body:"غادرت لشبونة مارو هونغ كونغ لنقل الأسرى إلى اليابان.",source:"history"},moji:{title:"ميناء موجي، اليابان",meta:"الوجهة التي لم تُبلغ",body:"يقع موجي في الاتجاه المخطط للرحلة. يمثل الخط المتقطع خطة، لا رحلة مكتملة.",source:"destination"},dongji:{title:"دونغجي، تشجيانغ",meta:"تشوشان · تشينغبانغ ومياوتسيهو",body:"يقع الحطام في المياه القريبة. أنقذ صيادو هذه الجزر الأسرى ورعوهم.",source:"history"},attack:{title:"الهجوم والغرق",meta:"1–2 أكتوبر 1942",body:"أطلقت USS Grouper طوربيدًا على السفينة التي غرقت في اليوم التالي. تتفرع عن هذا الحدث المسارات أدناه.",source:"history"},died:{title:"المتوفون",meta:"828 شخصًا · نحو 46%",body:"توفي 828 أسير حرب بريطانيًا خلال الرحلة والغرق والعنف المرتبط بهما.",source:"history"},captured:{title:"الأسرى، باستثناء من أنقذهم الصيادون",meta:"604 أشخاص · نحو 33%",body:"يُحسب العدد بطرح 828 و384 من 1,816، وفق قسم البيانات التاريخية. يتعلق التمييز بمسار الإنقاذ الأولي.",source:"history"},rescued:{title:"أنقذهم صيادون صينيون",meta:"384 شخصًا · نحو 21%",body:"يُحصي هذا العدد من انتُشلوا من البحر. أعقب الإنقاذ إعادة أسر 381 منهم.",source:"history"},rescue:{title:"إنقاذ الصيادين",meta:"198 صيادًا · إنقاذ 384 أسيرًا",body:"خرج صيادو تشينغبانغ ومياوتسيهو إلى البحر مرارًا ورعوا الناجين. يُحصي 198 المنقذين، ويُحصي 384 الأسرى الذين أُنقذوا.",source:"fishermen"},recaptured:{title:"أُنقذوا ثم أُسروا مجددًا",meta:"381 شخصًا · 384 − 3",body:"أعادت القوات اليابانية أسر 381 من الرجال الذين أنقذهم الصيادون. وهم جزء من مجموعة الـ384.",source:"history"},escaped:{title:"نجوا من إعادة الأسر",meta:"3 أشخاص · نحو 0.78% من 384",body:"آوى السكان فالاس وجونستون وإيفانز، وساعدوهم على مغادرة الجزر إلى الأمان عبر بر الصين الرئيسي.",source:"history"},britain:{title:"المملكة المتحدة",meta:"الرحلة اللاحقة، بشكل تخطيطي",body:"لم تكن رحلة مباشرة من دونغجي إلى المملكة المتحدة. سافر إيفانز عبر الهند وكندا قبل زيارة إنجلترا عام 1945.",source:"escape"}},note:"مخطط علاقات الأحداث: لا تعبر أحجام العقد عن الأعداد، والخطوط ليست مسارات دقيقة. النسب مقربة. العددان 381 وثلاثة جزء من 384، لا مجموعان إضافيان. يمثل الرابط إلى المملكة المتحدة رحلة لاحقة، لا رحلة مباشرة مشتركة للهاربين الثلاثة.",sourcesTitle:"المصادر التاريخية",historySource:"الرحلة والأرقام · LiMMA",fishermenSource:"198 صيادًا · تقرير شينخوا",escapeSource:"الرحلة اللاحقة · شهادة إيفانز",destinationSource:"موجي · ريتشارد غراهام"}
